document.querySelectorAll('[data-edit-name]').forEach(b=>b.onclick=()=>{const person=staff.find(s=>s.email===b.dataset.editName),cell=b.closest('td');cell.innerHTML='<form><label>Display name<input name="displayName" required maxlength="100"></label><button type="submit" class="primary">Save name</button> <button type="button" class="cancel-name">Cancel</button><div class="name-status" role="status"></div></form>';const form=cell.querySelector('form');form.elements.displayName.value=person.name;form.elements.displayName.focus();cell.querySelector('.cancel-name').onclick=()=>render();form.onsubmit=action(async()=>{const name=form.elements.displayName.value.trim();if(!name)throw Error('Enter a name.');check(await db.rpc('sc_manage_user',{store:selectedStore,target_email:person.email,display_name:name,store_role:'employee',operation:'rename'}));await load();flash('Display name updated.')})});
