function manageLists(){if(!manager())return;$('#view').innerHTML='<h1>Manage lists</h1><p>Archive finished lists to hide them from the active call list. Customer records, notes, follow-ups and reporting remain available.</p><section class="panel scroll"><table><thead><tr><th>List</th><th>Customers</th><th>Status</th><th>Action</th></tr></thead><tbody>'+lists.map(l=>'<tr><td>'+esc(l.name)+'</td><td>'+customers.filter(c=>inList(c,l.id)).length+'</td><td>'+(l.archived?'Archived':'Active')+'</td><td><button data-archive="'+l.id+'">'+(l.archived?'Restore list':'Archive list')+'</button></td></tr>').join('')+'</tbody></table>'+(lists.length?'':'<p>No lists imported yet.</p>')+'</section>';document.querySelectorAll('[data-archive]').forEach(b=>b.onclick=action(async()=>{const list=lists.find(l=>l.id===b.dataset.archive);check(await db.from('sc_lists').update({archived:!list.archived}).eq('id',list.id).select('id').single());await load();flash(list.archived?'List restored.':'List archived. Notes and call history are preserved.')}))}
function permissions(){if(!groupAdmin())return;const people=staff.filter(s=>s.active);if(!people.some(s=>s.email===permissionEmail))permissionEmail=people.find(s=>!s.is_group_admin)?.email||me.email;const person=people.find(s=>s.email===permissionEmail);$('#view').innerHTML='<h1>Dealership permissions</h1><p>Check which dealerships a person can access, and choose their role at each store.</p><section class="panel"><label>User<select id="permission-user">'+people.map(s=>'<option value="'+esc(s.email)+'" '+(s.email===permissionEmail?'selected':'')+'>'+esc(s.name)+' · '+esc(s.email)+'</option>').join('')+'</select></label>'+(person.is_group_admin?'<div class="callout">Group administrators have access to every dealership.</div>':'')+'<form id="permission-form"><div class="scroll"><table><thead><tr><th>Allow access</th><th>Dealership</th><th>Role</th></tr></thead><tbody>'+dealerships.map(d=>{const grant=storeAccess.find(a=>a.staff_email===permissionEmail&&a.dealership_id===d.id),checked=person.is_group_admin||!!grant;return '<tr><td><input type="checkbox" data-grant="'+d.id+'" aria-label="Access to '+esc(d.name)+'" '+(checked?'checked ':'')+(person.is_group_admin?'disabled':'')+'></td><td>'+esc(d.name)+'</td><td><select data-grant-role="'+d.id+'" aria-label="Role at '+esc(d.name)+'" '+(!checked||person.is_group_admin?'disabled':'')+'><option value="employee" '+(grant?.role==='employee'?'selected':'')+'>Employee</option><option value="manager" '+(person.is_group_admin||grant?.role==='manager'?'selected':'')+'>Manager</option></select></td></tr>'}).join('')+'</tbody></table></div><button class="primary" type="submit" '+(person.is_group_admin?'disabled':'')+'>Save dealership access</button><div id="permission-status" role="status" class="message"></div></form><div class="callout"><strong>Manager:</strong> manages that dealership’s customers, imports, users and reports.<br><strong>Employee:</strong> can view and work customer lists at checked dealerships. Unchecked stores cannot be opened.</div></section>';$('#permission-user').onchange=()=>{permissionEmail=$('#permission-user').value;render()};document.querySelectorAll('[data-grant]').forEach(input=>input.onchange=()=>{document.querySelector('[data-grant-role="'+input.dataset.grant+'"]').disabled=!input.checked});$('#permission-form').onsubmit=action(async()=>{const grants=Array.from(document.querySelectorAll('[data-grant]')).filter(input=>input.checked).map(input=>({dealership_id:input.dataset.grant,role:document.querySelector('[data-grant-role="'+input.dataset.grant+'"]').value}));const target=permissionEmail,personName=person.name,saveButton=$('#permission-form button[type="submit"]');saveButton.disabled=true;saveButton.textContent='Saving…';$('#permission-status').textContent='Saving dealership access…';try{check(await db.rpc('sc_set_user_stores',{target_email:target,grants}));await load();const summary=grants.map(g=>storeName(g.dealership_id)+' ('+(g.role==='manager'?'Manager':'Employee')+')').join(', ');const message='Saved for '+personName+': '+(summary||'No dealership access')+'. Select another person from the User dropdown to edit their permissions.';if($('#permission-status'))$('#permission-status').textContent=message;flash('Dealership access saved.')}catch(error){if($('#permission-status'))$('#permission-status').textContent='Not saved: '+error.message;throw error}finally{if(saveButton.isConnected){saveButton.disabled=false;saveButton.textContent='Save dealership access';}}})}
function dealershipSetup(){if(!groupAdmin())return;$('#view').innerHTML='<h1>Dealership setup</h1><p>'+dealerships.length+' dealerships configured. Add your remaining stores as they are ready to join.</p><section class="panel"><table><thead><tr><th>Dealership</th><th>Users with store access</th></tr></thead><tbody>'+dealerships.map(d=>'<tr><td>'+esc(d.name)+'</td><td>'+storeStaff(d.id).length+'</td></tr>').join('')+'</tbody></table></section><form id="add-dealership" class="panel"><h2>Add dealership</h2><label>Dealership name<input id="dealership-name" required maxlength="100" placeholder="Enter the dealership’s name"></label><button class="primary" type="submit">Add dealership</button><p class="small">A new dealership starts with empty lists. Use Dealership permissions to grant staff access.</p></form>';$('#add-dealership').onsubmit=action(async()=>{const id=check(await db.rpc('sc_add_dealership',{dealership_name:$('#dealership-name').value.trim()}));selectedStore=id;page='permissions';await load();flash('Dealership added. Select users and check their access.')})}
function groupReports(){const managed=dealerships.filter(d=>canReport(d.id));if(!managed.length)return;$('#view').innerHTML='<h1>Group reporting</h1><p>Compare only the dealerships where you have manager access.</p><div class="filters"><label>From<input id="group-from" type="date" value="'+today().slice(0,7)+'-01"></label><label>Through<input id="group-through" type="date" value="'+today()+'"></label><label>Dealership<select id="group-store"><option value="">All managed dealerships</option>'+managed.map(d=>'<option value="'+d.id+'">'+esc(d.name)+'</option>').join('')+'</select></label><label>Employee<select id="group-employee"><option value="">All employees</option>'+authorizedStaff(managed.map(d=>d.id)).map(s=>'<option value="'+esc(s.email)+'">'+esc(s.name)+'</option>').join('')+'</select></label></div><div id="group-result"></div>';function draw(){const shown=managed.filter(d=>!$('#group-store').value||d.id===$('#group-store').value);const eligible=authorizedStaff(shown.map(d=>d.id)),previous=$('#group-employee').value;$('#group-employee').innerHTML='<option value="">All employees</option>'+eligible.map(s=>'<option value="'+esc(s.email)+'">'+esc(s.name)+'</option>').join('');if(eligible.some(s=>s.email===previous))$('#group-employee').value=previous;const employee=$('#group-employee').value,from=$('#group-from').value,to=$('#group-through').value;const rows=shown.map(d=>{const ids=new Set(allCustomers.filter(c=>c.dealership_id===d.id).map(c=>c.id)),entries=allActivity.filter(a=>{const date=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Los_Angeles',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(a.created_at));return ids.has(a.customer_id)&&date>=from&&date<=to&&(!employee||a.employee_email===employee)}),attempted=new Set(entries.map(a=>a.customer_id)).size,reached=new Set(entries.filter(a=>a.made_contact).map(a=>a.customer_id)).size;return {store:d,attempts:entries.length,attempted,reached,voicemails:entries.filter(a=>a.left_voicemail).length,emails:entries.filter(a=>a.sent_email).length,booked:new Set(entries.filter(a=>a.booked).map(a=>a.customer_id)).size,overdue:allActivity.filter(a=>ids.has(a.customer_id)&&a.followup&&!a.followup_done&&a.followup<today()&&(!employee||a.employee_email===employee)).length}});const sum=k=>rows.reduce((n,r)=>n+r[k],0);$('#group-result').innerHTML=stats([[sum('attempts'),'Outreach attempts'],[sum('reached'),'Customers reached'],[sum('booked'),'Customers with bookings'],[sum('emails'),'Emails sent'],[sum('overdue'),'Currently overdue']])+'<section class="panel scroll"><table><thead><tr><th>Dealership</th><th>Outreach attempts</th><th>Customers attempted</th><th>Reached</th><th>Contact rate</th><th>Voicemails</th><th>Emails sent</th><th>Booked</th><th>Overdue now</th></tr></thead><tbody>'+rows.map(r=>'<tr><td><button class="link" data-open-report="'+r.store.id+'">'+esc(r.store.name)+'</button></td><td>'+r.attempts+'</td><td>'+r.attempted+'</td><td>'+r.reached+'</td><td>'+(r.attempted?Math.round(r.reached/r.attempted*100):0)+'%</td><td>'+r.voicemails+'</td><td>'+r.emails+'</td><td>'+r.booked+'</td><td>'+r.overdue+'</td></tr>').join('')+'</tbody></table></section><div class="callout">Activity dates use Pacific time. Overdue follow-ups show the current backlog. Results are staff-entered; call duration, completed service visits and revenue are not connected.</div>';document.querySelectorAll('[data-open-report]').forEach(b=>b.onclick=()=>{selectedStore=b.dataset.openReport;selected=null;page='reports';scopeStore();render()})}['#group-from','#group-through','#group-store','#group-employee'].forEach(s=>$(s).onchange=draw);draw()}
function reports(){if(!manager())return;$('#view').innerHTML=`<h1>Employee performance · ${esc(storeName())}</h1><p>Compare outreach activity and follow-through.</p><div class="filters"><label>From<input id="from" type="date" value="${today().slice(0,7)}-01"></label><label>Through<input id="through" type="date" value="${today()}"></label><label>Employee<select id="report-employee"><option value="">All employees</option>${storeStaff().map(s=>`<option value="${esc(s.email)}">${esc(s.name)}</option>`).join('')}</select></label><label>List<select id="report-list"><option value="">All lists</option>${lists.map(l=>`<option value="${l.id}">${esc(l.name)}</option>`).join('')}</select></label></div><div id="report-data"></div>`;function draw(){let ids=new Set(customers.filter(c=>!$('#report-list').value||inList(c,$('#report-list').value)).map(c=>c.id));let a=activity.filter(x=>{let date=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Los_Angeles',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(x.created_at));return date>=$('#from').value&&date<=$('#through').value&&ids.has(x.customer_id)&&(!$('#report-employee').value||x.employee_email===$('#report-employee').value)});let shown=storeStaff().filter(s=>!$('#report-employee').value||s.email===$('#report-employee').value);$('#report-data').innerHTML=stats([[a.length,'Outreach attempts'],[new Set(a.filter(x=>x.made_contact).map(x=>x.customer_id)).size,'Unique customers reached'],[new Set(a.filter(x=>x.booked).map(x=>x.customer_id)).size,'Customers with bookings'],[a.filter(x=>x.sent_email).length,'Emails sent'],[activity.filter(x=>ids.has(x.customer_id)&&x.followup&&!x.followup_done&&x.followup<today()&&(!$('#report-employee').value||x.employee_email===$('#report-employee').value)).length,'Currently overdue']])+`<section class="panel scroll"><table><thead><tr><th>Employee</th><th>Assigned now</th><th>Attempted customers</th><th>Outreach attempts</th><th>Reached</th><th>Voicemails</th><th>Emails sent</th><th>Contact rate</th><th>Booked customers</th></tr></thead><tbody>${shown.map(s=>{let b=a.filter(x=>x.employee_email===s.email),n=new Set(b.map(x=>x.customer_id)).size,r=new Set(b.filter(x=>x.made_contact).map(x=>x.customer_id)).size;return `<tr><td>${esc(s.name)}</td><td>${customers.filter(c=>ids.has(c.id)&&c.assigned_email===s.email).length}</td><td>${n}</td><td>${b.length}</td><td>${r}</td><td>${b.filter(x=>x.left_voicemail).length}</td><td>${b.filter(x=>x.sent_email).length}</td><td>${n?Math.round(r/n*100):0}%</td><td>${new Set(b.filter(x=>x.booked).map(x=>x.customer_id)).size}</td></tr>`}).join('')}</tbody></table></section><div class="callout">Contact rate = unique customers reached ÷ unique customers attempted. Results are staff-entered; completed service visits and revenue are not connected.</div><section class="panel"><h2>Activity in selected period</h2>${a.slice(0,100).map(x=>`<div class="history"><button class="link" data-customer="${x.customer_id}">${esc(customers.find(c=>c.id===x.customer_id)?.name||'Customer')}</button> · ${esc(staff.find(s=>s.email===x.employee_email)?.name)}<div>${esc(x.notes)}</div><div class="small">${esc(new Date(x.created_at).toLocaleString('en-US',{timeZone:'America/Los_Angeles'}))} PT</div></div>`).join('')||'<p>No activity in this period.</p>'}${a.length>100?'<p>Showing the most recent 100 entries.</p>':''}</section>`;bindCustomers()}['#from','#through','#report-employee','#report-list'].forEach(s=>$(s).onchange=draw);draw()}
function parseCSV(text){let rows=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('CSV has an unclosed quoted field.');row.push(cell);if(row.some(v=>v.trim()))rows.push(row);return rows}
const importFields=[['first_name','First name',['first','first name']],['last_name','Last name',['last','last name']],['name','Full name (if combined)',['customer name','full name','name']],['vehicle','Vehicle / model',['vehicle','model']],['year','Vehicle year (optional)',['year','model year']],['make','Vehicle make (optional)',['make','vehicle make','manufacturer']],['phone','Phone',['phone','phone number']],['email','Email',['email','email address']],['vin','VIN',['vin','vin#']],['last_service_date','Last service date',['last service date','last service date (qualifying service)']],['mileage','Mileage at last service',['mileage','last odometer mileage']],['declined_services','Declined services',['declined services','declined service','declined work','service description','recommendation','declined_services']]];
function uploadPage(){if(!manager())return;upload=null;$('#view').innerHTML=`<h1>Add service customers</h1><div class="callout">Import destination: <strong>${esc(storeName())}</strong></div><p>Upload the raw dealership CSV or a cleaned customer list.</p><section class="panel"><label>List name<input id="list-name" required maxlength="200" placeholder="Service customers"></label><label>Customer CSV<input id="file" type="file" accept=".csv,text/csv"></label><p class="small">Up to 5,000 rows and 2 MB. Includes first/last name, phone, email, vehicle, VIN, last service date and mileage. Map a service-description column to Declined services for MyKaarma exports. Original files are not stored.</p><div id="mapping"></div><div id="preview"></div></section>`;$('#file').onchange=action(async()=>{const f=$('#file').files[0];upload=null;$('#mapping').innerHTML='';$('#preview').innerHTML='';if(!f)return;if(f.size>2*1024*1024)throw Error('Choose a CSV smaller than 2 MB.');const rows=parseCSV((await f.text()).replace(/^\uFEFF/,''));if(rows.length<2||rows.length>5001)throw Error('CSV must contain a header and 1–5,000 customer rows.');upload={headers:rows[0],rows:rows.slice(1)};if(!$('#list-name').value.trim())$('#list-name').value=f.name.replace(/\.csv$/i,'').replace(/[_-]+/g,' ');$('#mapping').innerHTML='<h2>Match spreadsheet columns</h2>'+importFields.map(([key,label,aliases])=>{let index=upload.headers.findIndex(h=>aliases.includes(h.trim().toLowerCase()));return `<label class="mapping">${label}<select id="map-${key}"><option value="-1">Not included</option>${upload.headers.map((h,i)=>`<option value="${i}" ${i===index?'selected':''}>${esc(h)}</option>`).join('')}</select></label>`}).join('')+`<label>Assign customers to<select id="owner"><option value="">Unassigned</option>${storeStaff().map(s=>`<option value="${esc(s.email)}">${esc(s.name)}</option>`).join('')}</select></label><label>When a customer already exists<select id="import-mode"><option value="skip">Add new customers; leave existing customers unchanged</option><option value="update">Update existing customers and add new customers</option></select></label><p class="small">Matches use VIN and customer name. Without a VIN, matching requires name, vehicle and a shared phone or email. Existing assignments, notes and do-not-call flags are preserved. Older service dates and mileage do not replace newer records. Multiple possible matches are skipped for review.</p><button id="review">Review import</button>`;$('#review').onclick=()=>reviewUpload()})}
function importDate(value){if(!value)return null;let y,m,d,parts;if((parts=/^(\d{4})-(\d{1,2})-(\d{1,2})$/.exec(value))){[,y,m,d]=parts}else if((parts=/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/.exec(value))){[,m,d,y]=parts}else throw Error('Use YYYY-MM-DD or MM/DD/YYYY for last service dates.');let date=new Date(Date.UTC(+y,+m-1,+d));if(date.getUTCFullYear()!==+y||date.getUTCMonth()!==+m-1||date.getUTCDate()!==+d)throw Error('Invalid last service date.');return [+y,String(+m).padStart(2,'0'),String(+d).padStart(2,'0')].join('-')}
function importVehicle(vehicle, year, make) {
  if (!vehicle) return '';
  const embeddedYear = vehicle.match(/^(\d{4})(?:\.0+)?\s+(.+)$/);
  const model = embeddedYear ? embeddedYear[2] : vehicle;
  const modelYear = embeddedYear ? embeddedYear[1] : year.replace(/^(\d{4})\.0+$/, '$1');
  const inferredMake = /^(Accord|Civic|CR-V|HR-V|CR-Z|Crosstour|Fit|Insight|Odyssey|Passport|Pilot|Ridgeline|Element|Prelude|Prologue)(?:\s|$)/i.test(model) ? 'Honda'
    : /^(ADX|ILX|Integra|MDX|NSX|RDX|RL|RLX|RSX|TL|TLX|TSX|ZDX)(?:\s|$)/i.test(model) ? 'Acura'
    : /^(Ascent|Baja|BRZ|Crosstrek|Forester|Impreza|Legacy|Outback|Solterra|Tribeca|WRX)(?:\s|$)/i.test(model) ? 'Subaru' : '';
  const brand = make || inferredMake;
  const alreadyBranded = brand && (model.toLowerCase() === brand.toLowerCase() || model.toLowerCase().startsWith(brand.toLowerCase() + ' '));
  return [modelYear, alreadyBranded ? '' : brand, model].filter(Boolean).join(' ');
}
function importStoreKey(name) {
  const key = name.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().replace(/^spreen /, '');
  return key === 'corona' ? 'honda corona' : key;
}
function reviewUpload(){try{const indices=Object.fromEntries(importFields.map(([k])=>[k,+$('#map-'+k).value]));if(indices.name<0&&indices.first_name<0&&indices.last_name<0)throw Error('Match a full name or first/last name.');if(indices.vehicle<0)throw Error('Match the vehicle or model column.');const storeColumn=upload.headers.findIndex(h=>['dealership','dealer name','store name'].includes(h.trim().toLowerCase()));const destination=importStoreKey(storeName());let valid=[],missing=0,invalid=0,duplicates=0,wrongStore=0,seen=new Set();for(let r of upload.rows){if(storeColumn>=0&&importStoreKey(r[storeColumn]||'')!==destination){wrongStore++;continue}let c=Object.fromEntries(importFields.map(([k])=>[k,(r[indices[k]]||'').trim()]));c.name=c.name||[c.first_name,c.last_name].filter(Boolean).join(' ');if(!c.name||(!c.phone&&!c.email)){missing++;continue}c.vehicle=importVehicle(c.vehicle,c.year,c.make);delete c.year;delete c.make;if(c.name.length>200||!c.vehicle||(c.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(c.email))){invalid++;continue}try{c.last_service_date=importDate(c.last_service_date);let miles=c.mileage.replace(/,/g,'');if(miles&&!/^\d+$/.test(miles))throw Error('Invalid mileage');c.mileage=miles?Number(miles):null;if(c.mileage!==null&&!Number.isSafeInteger(c.mileage))throw Error('Invalid mileage')}catch(e){invalid++;continue}c.vin=c.vin.toUpperCase();let key=[c.name.toLowerCase(),c.vehicle.toLowerCase(),c.phone.replace(/\D/g,''),c.email.toLowerCase(),c.vin,c.declined_services].join('|');if(seen.has(key)){duplicates++;continue}seen.add(key);valid.push(c)}$('#preview').innerHTML=`<div class="callout">${valid.length} ready · ${missing} missing name/contact · ${invalid} invalid · ${duplicates} duplicate rows within this file skipped. ${wrongStore?`${wrongStore} rows excluded because their dealership does not match ${esc(storeName())}. `:''}${storeColumn<0?'This file has no dealership column. Verify the destination before importing. ':''}Existing matches will be linked to this list; the selected import option controls whether their details are updated.</div><div class="scroll"><table><thead><tr><th>Customer</th><th>Vehicle</th><th>VIN</th><th>Last service</th><th>Mileage</th><th>Declined services</th></tr></thead><tbody>${valid.slice(0,5).map(c=>'<tr>'+['name','vehicle','vin','last_service_date','mileage','declined_services'].map(k=>'<td>'+esc(c[k])+'</td>').join('')+'</tr>').join('')}</tbody></table></div><label class="check"><input type="checkbox" id="authorized"> I verified that this list belongs to ${esc(storeName())} and I am authorized to import it.</label><button id="import" type="button" class="primary" ${valid.length?'':'disabled'}>Import ${valid.length} customers</button><div id="import-message" role="status" aria-live="polite" class="callout">Ready to import. Your list name must be filled in above.</div>`;$('#import').onclick=action(async()=>{if(!$('#authorized').checked)throw Error('Confirm authorization before importing.');if(!$('#list-name').value.trim())throw Error('Enter a list name at the top of this page.');const button=$('#import');button.disabled=true;button.textContent='Importing…';flash('Saving '+valid.length+' customers. Please keep this page open.');try{const owner=$('#owner').value||null;const result=check(await db.rpc('sc_import_dealership_list',{dealership:selectedStore,list_name:$('#list-name').value.trim(),owner_email:owner,records:valid,update_existing:$('#import-mode').value==='update'}));page='list';await load();flash(storeName()+': '+result.added+' added · '+result.updated+' updated · '+result.existing_unchanged+' existing linked without changes · '+result.ambiguous_skipped+' ambiguous matches skipped.')}finally{if(button.isConnected){button.disabled=false;button.textContent='Import '+valid.length+' customers';}}})}catch(e){flash(e.message)}}
async function restoreSession(){try{const {session}=check(await db.auth.getSession());if(recoveryError){clearPasswordRecovery();forgotPasswordPage('','This sign-in or reset link is invalid or has expired. Request a new reset email below.');return}if(passwordRecovery){if(session){window.sessionStorage.setItem('sc-password-recovery','true');resetPasswordPage()}else{clearPasswordRecovery();forgotPasswordPage('','This reset link has expired. Request a new reset email below.')}return}if(session){await load()}else login()}catch(error){if(passwordRecovery){clearPasswordRecovery();forgotPasswordPage('','This reset link could not be verified. Request a new reset email below.')}else{login();authFormMessage(error.message||'Unable to restore your session. Please sign in again.')}}}
